import*as THREE from'three';import{Module,VisualJoint,materials}from'../../core/index.js';import{mesh,slab}from'../../modeling/parts.js';import{spec}from'./dimensions.js';
function section(parent,{w,h,depth,y,z=0,holes=[],material,name}){const part=slab(parent,w,h,depth,.18,[0,y,z],material,holes.map(p=>({...p,cy:p.cy-z})),.02);part.rotation.x=Math.PI/2;part.name='Unit3.96 plug '+name;return part;}
/** Exact U020 supplied female screw plug;dimensions reconstructed from its own photographs. */
