 const partitions=[];for(const x of[-7.65,-3.96,0,3.96,7.65]){const part=slab(frame,Math.abs(x)>7?.5:.4,9.6,6,.07,[x,5.6,-1.9],orange,[],.02);part.name='Unit3.96 plug molded independent contact channel partition';partitions.push(part);}const entry=section(frame,{w:15.8,h:7.2,depth:.65,y:11.25,z:1.1,holes:spec.terminal.pinX.map(cx=>({w:2.7,h:2.7,r:1.35,cx,cy:.4})),material:orange,name:'four real round wire-entry channels'}),springs=[],cages=[],heads=[],joints=[];
 for(const[i,x]of spec.terminal.pinX.entries()){for(const side of[-1,1])springs.push(mesh(frame,new THREE.BoxGeometry(.14,6.8,.7),metal,[x+side*.42,-2.4,-1],'Unit3.96 plug recessed female mating spring'));const cage=[];cage.push(mesh(frame,new THREE.BoxGeometry(2.7,.22,4.9),metal,[x,2.4,.9],'Unit3.96 plug fixed clamp rear web'));cage.push(mesh(frame,new THREE.BoxGeometry(2.7,7.9,.22),metal,[x,6.45,-1.45],'Unit3.96 plug fixed clamp floor'));for(const side of[-1,1])cage.push(mesh(frame,new THREE.BoxGeometry(.14,7.9,4.9),metal,[x+side*1.28,6.45,.9],'Unit3.96 plug fixed clamp cage side'));cage.push(mesh(frame,new THREE.BoxGeometry(2.5,7.2,.2),metal,[x,6.4,3.25],'Unit3.96 plug fixed pressure plate'));cages.push(cage);mesh(frame,new THREE.CylinderGeometry(.36,.36,.8,24).rotateX(Math.PI/2),metal,[x,5.2,3.75],'Unit3.96 plug physical fixed screw shank');
 const head=new THREE.Group();head.name='Unit3.96 plug actual cross-recess screw '+(i+1);mesh(head,new THREE.CylinderGeometry(1.03,1.03,.1,48).rotateX(Math.PI/2),dark,[0,0,.05],'Unit3.96 screw real recessed drive floor');const shape=new THREE.Shape();shape.absarc(0,0,1.03,0,Math.PI*2,false);const cross=new THREE.Path(),a=.76,t=.13,points=[[-t,-a],[t,-a],[t,-t],[a,-t],[a,t],[t,t],[t,a],[-t,a],[-t,t],[-a,t],[-a,-t],[-t,-t]];points.forEach(([x,y],n)=>n?cross.lineTo(x,y):cross.moveTo(x,y));cross.closePath();shape.holes.push(cross);mesh(head,new THREE.ExtrudeGeometry(shape,{depth:.32,bevelEnabled:false,curveSegments:40}),metal,[0,0,.1],'Unit3.96 screw genuine cross-recess metal head');
 const joint=this.add(new VisualJoint({id:'screw-'+(i+1),label:'Printed pin '+(i+1)+' screw-head visual angle',position:[x,5.2,4.18],axis:[0,0,1],meta:{visualRangeDeg:[-180,180],rangeEvidence:'UI preview angle only,not mechanical stops;own U020 product01 shows four independent cross-recess heads.Thread pitch and tightening displacement unconfirmed.',source:'https://static-cdn.m5stack.com/resource/docs/products/unit/396port/396port_01.webp',scope:'Externally requested visible screw-head angle/duration only;no axial travel,clamp movement,thread physics,force,wiring,routing,voltage,current,power,electrical or firmware behavior'}}),frame);joint.object3d.add(head);joint.object3d.quaternion.setFromAxisAngle(new THREE.Vector3(0,0,1),[.21,-.34,.58,-.18][i]);joint.restQuaternion.copy(joint.object3d.quaternion);joint.set({angleDeg:anglesDeg[i]});heads.push(head);joints.push(joint);}
